public class InnerKnowledgeBaseChunkingConfigurationFactory(Action<Humidifier.Wisdom.KnowledgeBaseTypes.ChunkingConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Wisdom.KnowledgeBaseTypes.ChunkingConfiguration>
{

    internal InnerKnowledgeBaseFixedSizeChunkingConfigurationFactory FixedSizeChunkingConfigurationFactory { get; set; }

    internal InnerKnowledgeBaseSemanticChunkingConfigurationFactory SemanticChunkingConfigurationFactory { get; set; }

    internal InnerKnowledgeBaseHierarchicalChunkingConfigurationFactory HierarchicalChunkingConfigurationFactory { get; set; }

    protected override Humidifier.Wisdom.KnowledgeBaseTypes.ChunkingConfiguration Create()
    {
        var chunkingConfigurationResult = CreateChunkingConfiguration();
        factoryAction?.Invoke(chunkingConfigurationResult);

        return chunkingConfigurationResult;
    }

    private Humidifier.Wisdom.KnowledgeBaseTypes.ChunkingConfiguration CreateChunkingConfiguration()
    {
        var chunkingConfigurationResult = new Humidifier.Wisdom.KnowledgeBaseTypes.ChunkingConfiguration();

        return chunkingConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Wisdom.KnowledgeBaseTypes.ChunkingConfiguration result)
    {
        base.CreateChildren(result);

        result.FixedSizeChunkingConfiguration ??= FixedSizeChunkingConfigurationFactory?.Build();
        result.SemanticChunkingConfiguration ??= SemanticChunkingConfigurationFactory?.Build();
        result.HierarchicalChunkingConfiguration ??= HierarchicalChunkingConfigurationFactory?.Build();
    }

} // End Of Class

